/// <summary>
/// Map entity to datasource
/// </summary>
/// <param name = "_entityCtx">Entity context</param>
/// <param name = "_dataSourceCtx">Datasource context</param>
public void mapEntityToDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    if (this.METChargeThroughInvoiceType && _dataSourceCtx.name() == dataEntityDataSourceStr(VendVendorParametersEntity, METVendParameters))
    {
        this.validateChargeThroughType(this.METChargeThroughInvoiceType);
    }

    next mapEntityToDataSource(_entityCtx, _dataSourceCtx);
}

/// <summary>
/// Vaidate Chargethrough type
/// </summary>
public void validateChargeThroughType(str _chargeThroughInvoiceType)
{
    DictEnum dictEnum = new DictEnum(enumNum(METInvoiceType));
    container chargeThroughInvoiceTypeCon, chargeThroughInvoiceLoc;
    int counter = 1, i;
    int maxIndex = dictEnum.values() - 1;

    for (i = 0; i <= maxIndex; i++)
    {
        chargeThroughInvoiceTypeCon += METChargeThroughInvEnumLookupTmp::labelText(dictEnum, dictEnum.index2Value(i));
    }

    chargeThroughInvoiceLoc = str2con(_chargeThroughInvoiceType, METConstants::Semicolon);

    while(conLen(chargeThroughInvoiceLoc) >= counter)
    {
        str invoiceType = conPeek(chargeThroughInvoiceLoc, counter);

        if (!conFind(chargeThroughInvoiceTypeCon, invoiceType))
        {
            throw error(strFmt("@MET:InvalidChargeThroughInvoiceType", invoiceType));
        }

        counter++;
    }
}
